mapper.sql:
SELECT a.id,a.code as code, a.status as status,a.remark, ad.id as detailId,ad.source_id, ad.source_detail_id, ad.source_code as sourceCode, ad.source_type, ad.business_code as businessCode, ad.business_type, ad.shop_id as shopId, ad.shop_name as shopName, ad.warehouse_id as warehouseId, ad.warehouse_name, ad.platform_sku_no as platformSkuNo,ad.sku_no as skuNo, ad.sku_id, ad.product_name, ad.init_receive_qty as initReceiveQty, cast(ad.init_transit_cost AS VARCHAR) as initTransitCost, cast(ad.init_transit_tariff AS VARCHAR) as initTransitTariff, cast(ad.init_estimated_cost AS VARCHAR) as initEstimatedCost, cast(ad.init_estimated_tariff AS VARCHAR) as initEstimatedTariff, cast(ad.weight_allocation AS VARCHAR) as weightAllocation, cast(ad.product_cost AS VARCHAR) as productCost, ad.exchange_rate as exchangeRate, ad.weight_unit,ad.currency, ad.currency_symbol,a.create_user_name as createUserName,a.create_time as createTime FROM init_first_mile_allocation a LEFT JOIN init_first_mile_allocation_detail ad ON ad.main_id=a.id and ad.is_deleted=false
${params.sqlMap.default} and a.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
a.create_time DESC,a.id

mapper.select:
SELECT COUNT(distinct a.id) AS count, a.status AS tabFlag FROM init_first_mile_allocation a WHERE a.is_deleted=false
${permissionSql}
GROUP BY a.status
